//! Generated byte streams from the weighted vocabulary in `streams/vocab.rs`, checked
//! against properties that need no second emulator:
//!
//! - no stream panics, and the cursor, margins and row lengths stay inside the screen;
//! - feeding a stream in one call and in random chunks ends in the same screen;
//! - the parser's run scans and the terminal's ASCII runs end where the byte-at-a-time
//!   path does;
//! - stable indexes stay monotonic and agree with the scrollback and the rows, and the
//!   scrollback limit holds;
//! - resizing narrower and wider keeps the invariants.
//!
//! The reflow round trip on plain text lives in `tests/reflow.rs`. Fixed seeds, so `cargo
//! test` is deterministic. The default is 5000 cases; `CMDTERM_VT_FUZZ_CASES` changes the
//! count.

mod streams {
    pub mod snapshot;
    pub mod vocab;
}

use cmdterm_vt::{Config, Size, Terminal};
use proptest::prelude::*;
use proptest::test_runner::{RngAlgorithm, RngSeed};
use streams::{snapshot, vocab};

fn cases() -> u32 {
    std::env::var("CMDTERM_VT_FUZZ_CASES")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(5000)
}

const SCROLLBACK: usize = 7;

fn config() -> Config {
    Config {
        scrollback: SCROLLBACK,
        ..Config::default()
    }
}

fn start(case: &vocab::Case) -> Terminal {
    Terminal::new(
        Size {
            rows: case.rows,
            cols: case.cols,
        },
        config(),
    )
}

/// Cursor, margins, row lengths and the scrollback limit.
fn check(t: &Terminal) -> Result<(), TestCaseError> {
    let s = t.size();
    let c = t.cursor();
    prop_assert!(c.row < s.rows && c.col < s.cols, "cursor {c:?} in {s:?}");
    let (top, bottom, left, right) = t.margins();
    prop_assert!(top <= bottom && bottom < s.rows && left <= right && right < s.cols);
    for y in 0..s.rows {
        prop_assert!(t.row(y).unwrap().len() <= s.cols, "row {y}");
    }
    prop_assert!(t.scrollback_len() <= SCROLLBACK);
    for i in 0..t.scrollback_len() {
        prop_assert!(t.screen().scrollback_row(i).unwrap().len() <= s.cols);
    }
    Ok(())
}

/// Stable indexes agree with the scrollback length and map to rows without gaps.
fn check_stable(t: &Terminal) -> Result<(), TestCaseError> {
    let s = t.screen();
    let rows = t.size().rows;
    let first = s.first_stable();
    prop_assert_eq!(s.stable_index(0), first + s.scrollback_len() as u64);
    prop_assert_eq!(
        s.stable_index(rows - 1) + 1,
        first + s.scrollback_len() as u64 + rows as u64
    );
    for stable in first..first + (s.scrollback_len() + rows) as u64 {
        prop_assert!(t.row_by_stable(stable).is_some(), "no row {stable}");
    }
    prop_assert!(t.row_by_stable(s.stable_index(rows - 1) + 1).is_none());
    Ok(())
}

/// Cuts `bytes` at positions taken from `cuts`, which may fall inside a UTF-8 sequence or
/// an escape sequence.
fn split<'a>(bytes: &'a [u8], cuts: &[usize]) -> Vec<&'a [u8]> {
    let mut at: Vec<usize> = cuts.iter().map(|c| c % (bytes.len() + 1)).collect();
    at.sort_unstable();
    at.dedup();
    let mut out = Vec::new();
    let mut start = 0;
    for a in at {
        out.push(&bytes[start..a]);
        start = a;
    }
    out.push(&bytes[start..]);
    out
}

proptest! {
    #![proptest_config(ProptestConfig { cases: cases(), rng_algorithm: RngAlgorithm::ChaCha, rng_seed: RngSeed::Fixed(0x5eed), failure_persistence: None, ..ProptestConfig::default() })]

    #[test]
    fn generated_streams_keep_the_invariants(case in vocab::case()) {
        let mut t = start(&case);
        let mut last_first = 0;
        for piece in &case.pieces {
            t.advance(piece);
            check(&t)?;
            check_stable(&t)?;
            // The alternate screen has no scrollback and its own indexes.
            if !t.modes().alt_screen {
                let first = t.screen().first_stable();
                prop_assert!(first >= last_first, "first stable index went back");
                last_first = first;
            }
        }
        let mut out = Vec::new();
        t.take_replies(&mut out);
        let _ = t.drain_events().count();
    }

    #[test]
    fn fast_paths_match_the_bytewise_path(case in vocab::case()) {
        let bytes = case.bytes();
        let mut fast = start(&case);
        fast.advance(&bytes);
        let mut slow = start(&case);
        slow.advance_bytewise(&bytes);
        prop_assert_eq!(
            snapshot::of_cmdterm(&fast),
            snapshot::of_cmdterm(&slow),
            "bytes: {}",
            vocab::escape(&bytes)
        );
        for y in 0..fast.size().rows {
            let (a, b) = (fast.row(y).unwrap(), slow.row(y).unwrap());
            prop_assert_eq!(a.cells(), b.cells(), "row {}", y);
            prop_assert_eq!(a.wrapped(), b.wrapped(), "row {}", y);
        }
        prop_assert_eq!(fast.cursor(), slow.cursor());
        prop_assert_eq!(fast.scrollback_len(), slow.scrollback_len());
        let (mut a, mut b) = (Vec::new(), Vec::new());
        fast.take_replies(&mut a);
        slow.take_replies(&mut b);
        prop_assert_eq!(a, b);
        prop_assert_eq!(fast.drain_events().collect::<Vec<_>>(), slow.drain_events().collect::<Vec<_>>());
    }

    #[test]
    fn chunking_does_not_change_the_final_screen(
        case in vocab::case(),
        cuts in prop::collection::vec(any::<usize>(), 0..24),
    ) {
        let bytes = case.bytes();
        let mut whole = start(&case);
        whole.advance(&bytes);
        let mut parts = start(&case);
        for chunk in split(&bytes, &cuts) {
            parts.advance(chunk);
        }
        prop_assert_eq!(
            snapshot::of_cmdterm(&whole),
            snapshot::of_cmdterm(&parts),
            "bytes: {}",
            vocab::escape(&bytes)
        );
        prop_assert_eq!(whole.scrollback_len(), parts.scrollback_len());
        prop_assert_eq!(whole.screen().first_stable(), parts.screen().first_stable());
    }

    #[test]
    fn narrow_then_wide_keeps_the_invariants(
        case in vocab::case(),
        narrow in 2usize..8,
        wide in 8usize..30,
        rows in 2usize..9,
    ) {
        let mut t = start(&case);
        t.advance(&case.bytes());
        t.resize(Size { rows, cols: narrow });
        check(&t)?;
        check_stable(&t)?;
        t.resize(Size { rows, cols: wide });
        check(&t)?;
        check_stable(&t)?;
        t.advance(&case.bytes());
        check(&t)?;
    }
}
